package com.oms.order.service;
import org.junit.jupiter.api.*;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.m;
import static org.junit.jupiter.api.Assertions.*;
class LuckyBagOrderTest {
 RefundBundleReturnTest f;
 @BeforeAll static void start(){RefundBundleReturnTest.start();}
 @BeforeEach void setup(){f=new RefundBundleReturnTest();f.setup();f.f.f.db.update("DELETE FROM oms_refund_lucky_unit_claim");long a=f.f.f.db.queryForObject("SELECT stock_source_id FROM oms_order_shipment_line WHERE sku_sn='A'",Long.class),b=f.f.f.db.queryForObject("SELECT stock_source_id FROM oms_order_shipment_line WHERE sku_sn='B'",Long.class);Map<String,Object> snap=m("business_type","LUCKY_BAG","quantity",2,"sku_sn","FD","goods_name","Lucky bag","revision",1,"units",Arrays.asList(m("unit_id",501,"unit",1,"components",Arrays.asList(m("sku_sn","A","quantity",1,"stock_source_id",a),m("sku_sn","B","quantity",1,"stock_source_id",b))),m("unit_id",502,"unit",2,"components",Arrays.asList(m("sku_sn","A","quantity",1,"stock_source_id",a),m("sku_sn","B","quantity",1,"stock_source_id",b)))));f.f.f.db.update("UPDATE oms_order_bundle SET business_type='LUCKY_BAG',quantity=2,snapshot=? WHERE id=?",encode(snap),f.bundle);f.f.f.db.update("UPDATE oms_order_line SET component_quantity=0,quantity=2 WHERE bundle_id=?",f.bundle);f.f.f.db.update("UPDATE oms_order_shipment_line SET quantity=2,shipped_quantity=2");}
 @AfterEach void cleanup(){f.f.f.db.update("DELETE FROM oms_refund_lucky_unit_claim");f.cleanup();}
 Map<String,Object> input(){Map<String,Object> r=f.input();r.put("unit_ids",Collections.singletonList(502));return r;}
 @Test void selectedBagReturnsOnlyItsOriginalComponentsAndReplayKeepsIdentity(){f.service.create("VERIFY",f.f.refund,input(),"test");assertEquals(2,f.f.f.db.queryForObject("SELECT SUM(quantity) FROM oms_refund_return_plan",Long.class));assertEquals(502,f.f.f.db.queryForObject("SELECT unit_id FROM oms_refund_lucky_unit_claim",Long.class));f.service.create("VERIFY",f.f.refund,input(),"test");assertEquals(2,f.f.f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan",Long.class));Map<String,Object> changed=input();changed.put("unit_ids",Collections.singletonList(501));assertThrows(IllegalArgumentException.class,()->f.service.create("VERIFY",f.f.refund,changed,"test"));}
 @Test void partialBagReturnRequiresAnExplicitOriginalUnit(){Map<String,Object> missing=input();missing.remove("unit_ids");assertThrows(IllegalArgumentException.class,()->f.service.create("VERIFY",f.f.refund,missing,"test"));assertEquals(0,f.f.f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_lucky_unit_claim",Long.class));}
 @Test void matchingSkuFromAnotherBatchCannotCompleteTheOriginalBag(){Map<String,Object> snap=m("units",Arrays.asList(m("unit_id",1,"components",Arrays.asList(m("sku_sn","A","quantity",1,"stock_source_id",11),m("sku_sn","B","quantity",1,"stock_source_id",12)))));assertEquals(0,OrderLuckyBags.completeSources(snap,new HashMap<Long,Long>(){{put(11L,1L);put(99L,1L);}}));assertEquals(1,OrderLuckyBags.completeSources(snap,new HashMap<Long,Long>(){{put(11L,1L);put(12L,1L);}}));}
 @Test void reportShowsOriginalBagSourcesAndReturnClaimSeparatelyFromGifts(){f.service.create("VERIFY",f.f.refund,input(),"test");Map<String,Object> p=OrderBundles.report(f.f.f.repo,"VERIFY",f.f.f.order).get(0);assertEquals("袋",p.get("sales_unit"));assertEquals(2,number(p,"shipped_sets"));List<Map<String,Object>> u=com.oms.common.lucky.LuckyBagRules.rows(p.get("units"));assertNull(u.get(0).get("return_refund_id"));assertEquals(f.f.refund,number(u.get(1),"return_refund_id"));}
 @Test void missingOriginalComponentShipmentCannotCreateAnyWholeBagPlan(){f.f.f.db.update("UPDATE oms_order_shipment_line SET shipped_quantity=0 WHERE sku_sn='B'");assertThrows(IllegalArgumentException.class,()->f.service.create("VERIFY",f.f.refund,input(),"test"));assertEquals(0,f.f.f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_lucky_unit_claim",Long.class));}
}
